        verifyCsrf();$action=(string)($_POST['action']??'save');
        if($action==='save'){
            $token=(string)($config['cron_token']??'');if($token==='')$token=bin2hex(random_bytes(24));
            $config=['enabled'=>isset($_POST['enabled']),'keep_database'=>max(2,min(365,(int)($_POST['keep_database']??30))),'keep_gui'=>max(2,min(104,(int)($_POST['keep_gui']??12))),'gui_interval_days'=>max(1,min(31,(int)($_POST['gui_interval_days']??7))),'cron_token'=>$token];
