        }elseif($action==='backup'){
            $result=runLocalBackup($config,false,true);$dbName=(string)($result['database']['filename']??'');$guiName=(string)($result['gui']['filename']??'');recordActivity(activityDb(),$admin,'backup-gemaakt','instellingen','backup','',$dbName.'; '.$guiName);$message='Database- en Applicatie- en bestandenback-up op de STRATO-webspace voltooid.';
